package in.kabadiwala.connect.dto; import in.kabadiwala.connect.model.Role; import jakarta.validation.constraints.*; public final class AuthDtos {private AuthDtos(){} public record OtpRequest(@Pattern(regexp="^[6-9]\\d{9}$") String mobile,@NotBlank String purpose){} public record OtpVerify(@Pattern(regexp="^[6-9]\\d{9}$") String mobile,@Pattern(regexp="\\d{6}") String otp,@NotBlank String purpose){} public record Register(@NotBlank String fullName,@Pattern(regexp="^[6-9]\\d{9}$") String mobile,@Size(min=8) String password,String language,Role role,String businessName,String email,String address,String city,String state,String pincode,String licenseNumber){} public record Login(@Pattern(regexp="^[6-9]\\d{9}$") String mobile,@NotBlank String password){} public record Token(String accessToken,String refreshToken,long expiresInSeconds,String role,String name){} public record Refresh(String refreshToken){} }
